function growthRollup(products=[]){let parts=[['Core Growth Platform',4820]],conversions=908,campaigns=14;if(products.includes('Social Ads')){parts.push(['Social Ads',2186]);conversions+=642;campaigns+=96}if(products.includes('Leads')){parts.push(['Leads boost',4820]);conversions+=598}if(products.includes('SEO')){parts.push(['SEO',1180]);conversions+=146}let total=parts.reduce((sum,x)=>sum+x[1],0);return{totalLeads:total.toLocaleString(),conversions:conversions.toLocaleString(),activeCampaigns:campaigns.toLocaleString(),parts,boosts:parts.slice(1).map(x=>x[0])}}
function GrowthRollupBanner({rollup}){return <div className="growthRollup"><div><b>Growth Platform aggregate</b><span>{rollup.boosts.length?'Includes '+rollup.boosts.join(', '):'Core Growth Platform only'}</span></div>{rollup.parts.map(([name,value])=><span key={name}><small>{name}</small><strong>{value.toLocaleString()} leads</strong></span>)}<span className="rollupTotal"><small>Combined total</small><strong>{rollup.totalLeads} leads</strong></span></div>}
