function Dashboard({demoPackage,setDemoPackage,demoAudience,setDemoAudience,demoProducts,setDemoProducts}){return <main className="homeDashboard"><div className="homeTitle"><h1>Home</h1><button><CalendarDays/> Last 30 days⌄</button></div><DemoTools pkg={demoPackage} setPkg={setDemoPackage} audience={demoAudience} setAudience={setDemoAudience} products={demoProducts} setProducts={setDemoProducts}/>{demoProducts.includes('Thryv Growth Platform')&&<GrowthPlatformOverview products={demoProducts}/>}{demoProducts.includes('Business Center')&&<BusinessCenterOverview/>}{demoProducts.includes('SEO')&&<SeoOverview/>}{demoProducts.includes('Leads')&&<LeadsOverview/>}{demoProducts.includes('Social Ads')&&<SocialAdsOverview/>}{demoProducts.includes('Keap')&&<KeapOverview/>}</main>}
function DemoTools({pkg,setPkg,audience,setAudience,products,setProducts}){let [open,setOpen]=useState(false);let toggleProduct=name=>setProducts(current=>{let boosts=['SEO','Social Ads','Leads'];if(name==='Thryv Growth Platform'&&boosts.some(x=>current.includes(x)))return current;if(current.includes(name))return current.filter(x=>x!==name);return boosts.includes(name)?[...new Set([...current,'Thryv Growth Platform',name])]:[...current,name]});return !open?<button className="demoToolsTrigger" aria-label="Open demo tools" onClick={()=>setOpen(true)}><SlidersHorizontal/> Demo tools</button>:<section className="demoTools" aria-label="Demo tools"><div className="demoToolsTitle"><div><h2>Demo tools</h2><p>Preview commercial configurations</p></div><div className="demoTitleActions"><span>Demo only</span><button aria-label="Collapse demo tools" onClick={()=>setOpen(false)}>Hide</button></div></div><div className="demoControls"><fieldset><legend>Audience</legend><div className="segments">{['Partners','Agency','Franchise','Enterprise'].map(name=><button type="button" aria-pressed={audience===name} className={audience===name?'selected':''} onClick={()=>setAudience(name)} key={name}>{name}</button>)}</div></fieldset><fieldset><legend>Package</legend><div className="segments">{['Base','Analytics +','Manage +','All'].map(name=><button type="button" aria-pressed={pkg===name} className={pkg===name?'selected':''} onClick={()=>setPkg(name)} key={name}>{name}</button>)}</div></fieldset><fieldset className="productsControl"><legend>Products <small>Multi-select</small></legend><div className="segments productSegments">{['Keap','Thryv Growth Platform','SEO','Social Ads','Leads','Business Center'].map(name=><button type="button" aria-pressed={products.includes(name)} className={products.includes(name)?'selected':''} onClick={()=>toggleProduct(name)} key={name}>{products.includes(name)&&<span>✓</span>}{name}</button>)}</div></fieldset></div></section>}
